package com.tracksphere.application.auth;
import com.tracksphere.application.auth.dto.*; import com.tracksphere.domain.model.*; import com.tracksphere.domain.repository.*; import com.tracksphere.infrastructure.security.*; import lombok.RequiredArgsConstructor; import org.springframework.security.authentication.BadCredentialsException; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.security.SecureRandom; import java.time.Instant; import java.util.*;
@Service @RequiredArgsConstructor @Transactional public class AuthService { private final UserRepository users; private final RoleRepository roles; private final RefreshTokenRepository tokens; private final PasswordEncoder passwords; private final JwtService jwt; private final JwtProperties properties; private final UserMapper mapper; private final SecureRandom random=new SecureRandom();
 public AuthResponse register(RegisterRequest request){String email=request.email().trim().toLowerCase(Locale.ROOT);if(users.existsByEmailIgnoreCase(email))throw new IllegalArgumentException("Email is already registered");Role role=roles.findByName("ROLE_USER").orElseThrow(()->new IllegalStateException("Default role is missing"));User user=users.save(new User(email,passwords.encode(request.password()),request.firstName().trim(),request.lastName().trim(),new HashSet<>(Set.of(role))));return issue(user);}
 public AuthResponse login(LoginRequest request){User user=users.findByEmailIgnoreCase(request.email().trim()).orElseThrow(()->new BadCredentialsException("Invalid email or password"));if(!user.isEnabled()||!passwords.matches(request.password(),user.getPasswordHash()))throw new BadCredentialsException("Invalid email or password");return issue(user);}
 public AuthResponse refresh(RefreshTokenRequest request){RefreshToken old=tokens.findByToken(request.refreshToken()).orElseThrow(()->new BadCredentialsException("Invalid refresh token"));if(!old.isUsable())throw new BadCredentialsException("Invalid refresh token");old.revoke();return issue(old.getUser());}
 private AuthResponse issue(User user){String raw=randomToken();tokens.save(new RefreshToken(raw,user,Instant.now().plus(properties.refreshTokenExpiration())));return new AuthResponse(jwt.createAccessToken(user),raw,mapper.toResponse(user));} private String randomToken(){byte[] bytes=new byte[48];random.nextBytes(bytes);return Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);} }
